PRAGMA foreign_keys = ON;
CREATE TABLE businesses (id TEXT PRIMARY KEY, name TEXT NOT NULL, business_type TEXT, timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE business_users (business_id TEXT NOT NULL REFERENCES businesses(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','manager')), permissions_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(business_id,user_id));
CREATE TABLE branches (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), name TEXT NOT NULL, parent_id TEXT REFERENCES categories(id), UNIQUE(business_id,name));
CREATE TABLE products (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), category_id TEXT REFERENCES categories(id), sku TEXT, name TEXT NOT NULL, brand TEXT, unit TEXT NOT NULL DEFAULT 'pcs', attributes_json TEXT NOT NULL DEFAULT '{}', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX products_business_idx ON products(business_id,active);
CREATE TABLE product_variants (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), product_id TEXT NOT NULL REFERENCES products(id), variant_label TEXT NOT NULL DEFAULT '', barcode TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', UNIQUE(business_id,product_id,variant_label));
CREATE TABLE inventory_snapshots (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), branch_id TEXT NOT NULL REFERENCES branches(id), variant_id TEXT NOT NULL REFERENCES product_variants(id), expected_quantity REAL NOT NULL CHECK(expected_quantity>=0), source TEXT NOT NULL DEFAULT 'manual', import_batch_id TEXT, captured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inventory_import_batches (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), branch_id TEXT REFERENCES branches(id), file_name TEXT, imported_by TEXT REFERENCES users(id), row_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audits (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), branch_id TEXT NOT NULL REFERENCES branches(id), name TEXT NOT NULL, join_code_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','active','review','approved','archived')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, approved_at TEXT);
CREATE INDEX audits_business_idx ON audits(business_id,created_at);
CREATE TABLE audit_assignments (id TEXT PRIMARY KEY, audit_id TEXT NOT NULL REFERENCES audits(id), employee_name TEXT NOT NULL, access_token_hash TEXT NOT NULL, scope_json TEXT NOT NULL DEFAULT '{}', revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_count_entries (id TEXT PRIMARY KEY, audit_id TEXT NOT NULL REFERENCES audits(id), business_id TEXT NOT NULL REFERENCES businesses(id), variant_id TEXT NOT NULL REFERENCES product_variants(id), quantity REAL NOT NULL CHECK(quantity>=0), counted_by TEXT NOT NULL, counted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, note TEXT, status TEXT NOT NULL DEFAULT 'submitted', idempotency_key TEXT UNIQUE);
CREATE INDEX count_entries_audit_idx ON audit_count_entries(audit_id,variant_id);
CREATE TABLE audit_count_revisions (id TEXT PRIMARY KEY, count_entry_id TEXT NOT NULL REFERENCES audit_count_entries(id), old_quantity REAL NOT NULL, new_quantity REAL NOT NULL, changed_by TEXT NOT NULL, reason TEXT NOT NULL, changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_requests (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), audit_id TEXT NOT NULL REFERENCES audits(id), requested_by TEXT NOT NULL, proposed_product_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reviewed_by TEXT, reviewed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_activity_logs (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), audit_id TEXT REFERENCES audits(id), actor TEXT NOT NULL, action TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
